-- Fire-and-forget: app.health.* keys for the Versions / System Info panel
-- (BrowserClientInfo + health status labels). The FE en-GB fallback covers
-- English only; the DB owns the translations for every language.
--
-- Languages: en-GB, en-US, it-IT, fr-FR, es-ES, de-DE, pt-PT
-- Idempotent via ON CONFLICT.

BEGIN;

ON CONFLICT (key, language) WHERE deleted_at IS NULL DO NOTHING;

COMMIT;
